shots=[
dict(id='A01',name='上方谷-雨幕压住火线',theme='上方谷雨灭',duration=6,edit='建议取3—4秒',refs=[(R/'references/A01-谷地火场实际首帧.png','真实火场空间母版；地形、焦木、帐架和原有火点，不参考原片中火势反弹')],camera='35mm自然广角，地面略高处向谷地看；横移不超过30厘米，不能升空绕山。',start='谷地已经下雨；近处黑木架、中景营道、远处山坡三层空间可读。火集中在原有几处，不是漫山火海。',beats=[('0—2秒','稳住原有谷地尺度；近处木架占一角，雨幕遮住较远山体。'),('2—4秒','同一阵雨向谷地中景推进，暴露在雨中的小火舌逐步变低；遮挡处少量火点仍存。'),('4—6秒','雨幕变密，木架上的水流汇入营道；远处层次仍能辨认，不用白雾盖掉整个场景。')],end='大部分画面转为湿黑与灰烟，少量被遮蔽的残火保持可信，为焦木近景留出动机。',sound='连续密集雨声，远火由强变弱，低处流水渐清；只用自然环境动态，不加轰鸣配乐。',seam='在雨幕变密时直接切A02的湿木纹理；保持同一条雨声，不能火焰变形为人物或地图。',prompt='6秒单镜头，16:9真人历史电影影像。严格保持参考图的真实谷地、黑木架、营道与坍塌帐架的大小和位置。相机在地面略高处，35mm自然广角，只横移约30厘米，前景焦木产生轻微视差，中景营道和远山仍可辨。开头就有雨，雨幕从较远谷地向中景加密；暴露处原有的小火舌被雨逐步压低，遮蔽处只剩少量低火。湿木表面逐渐变黑发亮，水流沿原有坡向汇入营道，灰烟薄而不遮满画面。空间规模来自三层真实纵深。只保留参考中的营地，不新增整齐军阵、人物或城池。不让火势反弹，不出现爆炸、火墙、巨浪或岩浆，不模拟太阳突然升起。没有人声、对白、旁白或字幕。声音只有连续雨、远处火和近处水流；完全无音乐、无低音铺底。',checks=['火势变化有局部雨水原因，不能整片同时瞬灭或反向变大。','相机有轻微真实视差；不靠拉伸山体或加大火焰制造规模。']),
dict(id='A02',name='上方谷-一截余炭暗下',theme='上方谷雨灭',duration=4,edit='建议取1.5—2.5秒',refs=[(R/'references/A02-余炭实际首帧.png','地面与焦木实拍感母版，保留木架斜线、湿泥和局部暗红炭芯')],camera='50mm正常透视，低机位近景，镜头固定，焦木和汇水处同时清楚。',start='泥地已经湿透，只在一截焦木的裂缝里留一点暗红，明火不占画面。',beats=[('0—1秒','雨点落在原有积水和木头上，产生小而密的水纹。'),('1—3秒','水沿木头表面流过，暗红炭芯逐渐变暗，一缕很薄的蒸汽离开表面。'),('3—4秒','黑木与流水继续存在，保留灾后的空与静，不再次点火。')],end='红光消失，湿木纹理和真实水流仍清楚。',sound='雨点击打、极轻湿木嘶声和细水；禁用夸大的灭火爆声。',seam='A03人物目光指向画面左下；本镜是他所看的地面，不是假装地面燃烧重启。',prompt='4秒连续的真实湿炭近景，16:9。以参考图为准确地面和木头布局。50mm正常透视固定低机位，泥土、木炭裂纹与细水同时清楚。开头只保留木炭裂缝中的一点暗红，没有高火苗。细密雨点落下形成小水纹，薄水流沿木头纹理流动，局部暗红在约两秒内缓慢变暗，只有极薄的蒸汽。最后一秒仍看见黑炭和流水。整块木头不移动，不变形，不突然凭空消失。没有大水滴、碗形水冠、爆炸或大团白烟；不增加新火、不逆转火势。画面没有人物、文字或字幕。声音只有真实小雨、细水和很轻的湿木嘶声；无人声、无对白、无旁白、无音乐。',checks=['不用上一版R04RR原片0.75—2秒的异常水冠或火焰作为动作参考。','黑炭仍保留体积和纹理，不用一层雾掩盖变化失败。']),
dict(id='A03',name='上方谷-诸葛亮看向湿炭',theme='上方谷雨灭',duration=5,edit='建议取2—3秒',refs=[(P/'PV-H3-20261115-v2.5/references/R05-诸葛亮雨营反应.png','唯一人物与场景母版：同一演员、黑冠、湿蓝灰袍，实际地面营地；不使用被弃用R05视频')],camera='50mm半身中近景，地面高度；锁机位，雨滴、呼吸和焦外帆布构成真实动态。',start='人物位于右侧，视线落在左下的焦木；羽扇低持，手和扇留在腹前。',beats=[('0—2秒','先停在左下目光，雨水沿冠缘与胡须滴落，嘴保持闭合。'),('2—4秒','一次自然眨眼，肩背随短促鼻息略沉，手和羽扇保持原位。'),('4—5秒','保留一拍不动的目光；不是仰天说台词，也不再次举扇。')],end='低位扇与闭口表情仍清楚，眼神留在左下。',sound='同一场雨延续，加一口很轻鼻息与湿衣料声。',seam='可在一滴水从扇羽落下后切B01的风中布带；先切画面，再换环境声，不能把雨带进关羽平原。',prompt='5秒安静的真人电影人物反应，16:9。完整保留参考图中同一演员、冠帽、湿衣、胡须、低位羽扇及已经烧毁的泥地营地。相机固定在半身中近景，人物在画面右侧，始终低眼看画面左下的地面，嘴唇始终闭合。只发生一次轻微眨眼和自然鼻息，肩背随呼吸略沉。右手与羽扇保持参考图位置，不抬扇、不挥扇、不抬头看天、不转身。雨滴顺冠缘、胡须和羽毛落下，后方湿帆布轻动。保持真实人物尺度与中性阴雨天光，不增加山崖、巨大山谷、火海或任何新人物。背景只有湿黑木架和坍塌帆布，不新增火苗。声音仅为持续雨声、一口轻鼻息和湿布料；无人说话，无旁白、无音乐、无字幕。',checks=['口型、抬扇或背景重新起火任一出现，不能仅靠静音当作合格。','不要复用R05视频：其额外说话、抬扇和音乐已被弃用；R06仅可作动作尺度参考。']),
dict(id='B01',name='关羽-远阵压住一人',theme='关羽人去刀留',duration=6,edit='建议取3—4秒',refs=[(BASE/'existing/E05-关羽持刀.png','锁定关羽演员、绿巾衣甲、左侧站位、整把长柄刀和湿地远军列')],camera='40—50mm正常透视全身景，低于胸口、保持地平线；横移约40厘米，前景芦苇轻掠一侧。',start='关羽在左，长刀立在身旁；远方军列只是低而远的压力，不涌成贴脸人海。',beats=[('0—2秒','先给全身、完整刀柄与远方军列同框；衣摆和巾带随同一方向风动。'),('2—4秒','关羽视线缓缓落向握柄的手，身形仍稳，不跪倒、不摆攻击姿态。'),('4—6秒','握柄指节由紧变松，刀柄轻倾几度；动作尚未完成就留给剪辑接落地结果。')],end='手已松，刀尚未凭空消失；最后可用的帧须看清原持握关系。',sound='开阔风、近处衣甲轻擦、手掌磨木柄；远军只留极弱脚步，不喊整齐口号。',seam='接B02地面结果，落刀声音跨切点；明确采用省略剪辑，不声称两镜拍到了完整坠落过程。',prompt='6秒真人历史电影全身景，16:9。精确保留参考图中的关羽演员、绿巾、旧衣甲、左侧站位、长柄刀完整形制和远处湿地军列。40到50mm正常透视，相机在低于胸口的高度缓慢横移约40厘米，仅让近处芦苇产生轻微视差。人物和整把竖立长刀始终可读，远军始终保持在原有地平线处。关羽先站稳，随后眼睛自然落向持刀的手，指节逐步松开，刀柄只倾斜几度。衣摆、巾带与芦苇受到同向风。不开口，不表演痛哭，不跪倒，不挥刀，不让武器变短或消失。相机不环绕，不俯冲，不增加城楼或密集冲锋兵。不加新伤口或死亡动作。只留开阔风声、衣甲轻擦、掌心与木柄摩擦，远处极弱脚步；没有对白、旁白、音乐或字幕。',checks=['规模来自人、刀与远阵的比例，不让军列贴近或整齐复制。','不能把长柄刀变短刀；刀、手与地面接触关系须真实。']),
dict(id='B02',name='关羽-刀留在泥地',theme='关羽人去刀留',duration=5,edit='建议取2—3秒',refs=[(BASE/'existing/E06-关羽落刀.png','已落地的完整长柄刀与红缨结果构图；不是坠落动作起始帧')],camera='50mm低机位，整柄刀斜穿前后景；镜头向前移动约15厘米，始终保留完整长柄识别。',start='刀已经躺在泥地，构图按原图；不再要求模型把同一把刀从空中落一次。',beats=[('0—1秒','红缨最后几根纤维贴近湿地，水洼泛起很小的残余水纹。'),('1—3秒','红缨止住，刀身保持重量；后方远阵在薄雾里，前景不出现尸体。'),('3—5秒','风掠过芦苇和衣料边缘，镜头略向前移，刀刃反光随视差自然变化。')],end='最后留住完整长柄、刀刃与静下来的红缨。',sound='首帧前用一次克制泥地接触声承接B01，随后只留风；不把地面结果配成反复金属碰撞。',seam='刀的上左—下右斜线接C01低位刑刀。画面先交代马谡、绳索和刀斧手，避免误读成斩杀关羽。',prompt='5秒真人电影地面结果镜头，16:9。参考图是已经落地的最终状态，完整保留同一长柄刀、刀刃、红缨、湿泥与远阵。不要再做一次从空中落刀。50mm低机位，相机仅向前移动约15厘米，整条长柄仍可辨。开头红缨末端轻轻贴下湿地，小水纹扩散；随后刀完全静止，只有芦苇、远处雾和极轻的衣料边缘受风移动。长刀始终有真实重量，不弹跳，不融入地面，不变成短刀；不新增人体、血迹或新人物。自然夕照只保留在局部反光，不给全画面加橙色滤镜。声音只有风、轻微水纹与一次很轻的纤维触地；无人声、无对白、无旁白、无音乐或字幕。',checks=['落地结果不能被描述为完整落刀动作已验证。','镜头推进时不能裁到无法辨认长柄，红缨不得持续弹跳。']),
dict(id='C01',name='马谡-刑场原图与抬眼',theme='马谡与诸葛亮',duration=5,edit='建议取2—3秒，保留原速',refs=[(BASE/'existing/E07-马谡刑场.png','用户指定唯一马谡母版；左前刀斧手、中央被缚马谡、后方两名卫兵，四人构图不改')],camera='严格保持E07的中景构图与机位；不环绕、不拉远、不生成新的双人母镜。',start='马谡跪地向右上看，刀斧手在左前方，刑刀低位斜过前景，右前方为空地。',beats=[('0—2秒','保持原图眼神与跪姿，绳索和双手背缚关系不变；刀斧手等待。'),('2—4秒','仅一次轻眨眼和一口压低的鼻息，衣料轻动，嘴保持闭合。'),('4—5秒','视线仍朝右上，刀仍放低；不给摇头、哭喊、猛然垂首或起身动作。')],end='马谡目光仍在右上，剪到C02诸葛亮左下看的反打。',sound='安静营地风、旗绳、粗布衣料和马谡鼻息；无对白，不能偷放求饶或导演说明。',seam='诸葛亮在马谡前方偏右、相隔数步的监斩台案后。相机不越轴。此空间说明只用于剪辑检查，API正文不描述画外诸葛亮，以防模型添人。',prompt='Animate this exact photograph as a five-second restrained live-action shot, 16:9. Preserve the exact FOUR existing people and the original framing: the cropped executioner in the far LEFT foreground with his lowered diagonal dao, the bound kneeling man at CENTER, and the TWO distant spear guards behind. The right foreground remains EMPTY BARE EARTH throughout. Camera is locked with identical framing and scale. The kneeling man maintains the reference head angle and upward-right eye direction; his lips remain closed. One slight blink and a quiet nasal breath, with tiny cloth movement. The executioner waits motionless; his hand and lowered blade remain in their original positions. Distant flags move gently in the same breeze. Preserve every face, rope, hand, weapon, outfit, tent and fence. No entering people, no foreground additions, no head turn, no camera movement, no cuts, no text. Sound consists only of quiet nasal breathing, coarse cloth and camp wind. No words, no voice, no singing and no music.',checks=['只允许E07；禁用M04新图及派生视频，禁用旧R03马谡诸葛亮同场替代图。','生成右前方官员即弃用，不用裁切掩盖；保留刀斧手及低刀。','M06末段曾产生多余口型，须查实际输出，不因Prompt写了闭口就判通过。']),
dict(id='C02',name='诸葛亮-迟举的羽扇',theme='马谡与诸葛亮',duration=6,edit='建议取3—4秒，动作完整',refs=[(BASE/'existing/E10-诸葛亮监斩中景.png','唯一监斩台母版：同一演员、蓝灰袍、黑冠、桌案、灰褐羽扇和台阶')],camera='50mm中景，保留案桌与低台的边缘作为空间证据，固定同轴机位。',start='诸葛亮在画面偏右，先看左下；左手撑案，右手低持羽扇。',beats=[('0—2秒','接住左下的目光，嘴闭合，一次浅呼吸；不立即把扇举到脸前。'),('2—4秒','眼睛先垂低，肘与前臂随后带动羽扇上移，手腕轻转，不换手。'),('4—6秒','扇自然遮住眉眼至鼻梁，头略低；左手始终撑在同一案边。')],end='扇遮眼，胡须可留在下缘，身体与案桌仍可读。',sound='与C01同一营地风，袖口、羽毛和木案轻响；呼吸很轻，不哭喊、不讲话。',seam='C01右上望→C02左下看，保持反打。切D01可用帐布声先入，明确场景转换，不做脸部衰老变形。',prompt='6秒连续真人表演，16:9，严格保持参考图监斩台、演员、黑色竖纹冠、蓝灰衣袍、灰褐羽扇与木案。50mm固定中景，案边和低台仍在画面内。人物先保持向画面左下方的目光，嘴闭合；左手稳稳撑在原案边，右手低持原羽扇。两秒后先垂眼，再由肘与前臂带动羽扇缓慢举起，手腕自然转动，使扇面遮住眉眼和鼻梁；最后保留一拍略低的头。扇从起点到终点是同一把，大小、羽根和握柄关系不变；不能凭空长大、穿过脸或胡须，不换手，不抖肩哭喊，不说话，不转身。不出现新的前景人物，不改成雨景，不跨到相反机位。只有同一营地的轻风、衣袖与扇羽摩擦、浅呼吸；无对白、无旁白、无音乐或字幕。',checks=['须保留完整举扇轨迹，不接受只有静态掩面图的慢推。','扇宽不足以掩面时先记录参考不足，不靠动态膨胀解决。','不把马谡放在诸葛亮背后或右侧近身，不将左下视线改成望镜头。']),
dict(id='D01',name='五丈原-地图前停住的手',theme='五丈原灯前未竟',duration=6,edit='建议取3—4秒',refs=[(BASE/'new/N05-五丈原-灯前未竟-v1.png','锁定夜帐演员、旧黑袍、灰须、左手羽扇、右手地图和右侧桌灯；不是七星灯阵')],camera='50mm桌边侧面中景；先让帐门纵深与人、地图、灯同框，缓慢前移15厘米。',start='诸葛亮坐在案左，右手已经悬在地图边缘，左手握扇；右侧一盏小油灯稳定燃烧，帐门外仅有远灯。',beats=[('0—2秒','先看见人、地图、灯与帐门的纵深，帐布在真实来风中轻动。'),('2—4秒','右手指尖向地图边缘再接近少许，却悬停在纸面上方；左手和羽扇不换位置。'),('4—6秒','一口浅呼吸使肩背略沉，手没有落下；桌上灯仍亮，不提前灭灯。')],end='手仍悬在地图上方，灯稳定在画面右侧，接灯的近景。',sound='帐外风与很远的两三步脚步，帐内浅呼吸、布料；无战报、无解释遗言。',seam='D02使用同一盏灯、同一桌边与右手方位。若补近景首帧，优先从D01实际选用末帧提取或以此约束，不换灯器。',prompt='6秒真人历史电影夜帐镜头，16:9。以参考图锁定同一诸葛亮演员、旧黑袍、黑冠、灰须、帐篷、木案、地图和右侧单盏小油灯。50mm桌边侧面中景，人物在左，地图在下部，右侧油灯与帐门纵深同时可见。相机缓慢向前约15厘米。左手始终握住原羽扇，右手已经悬在地图边缘，指尖只再接近纸面少许便停住，始终不触纸。肩背随一次浅呼吸略沉，动作克制；保持真实手指与关节，不用夸张颤抖。灯保持稳定，帐布在风中轻动，帐外远灯不变成密集军阵。嘴闭合，不写字，不摊开新地图，不抬扇，不增加七星灯阵。声音仅为帐外风、极远脚步、帐布、浅呼吸和衣料，无战报、对白、旁白、音乐或字幕。',checks=['悬停须在画面里能看懂，不能指尖穿纸或到处画图。','这是单盏桌灯意象，不把现图误称七星主灯；不要把夜帐人物骤变成另一位演员。']),
dict(id='D02',name='五丈原-一盏灯灭',theme='五丈原灯前未竟',duration=5,edit='建议取2—3秒，余烟留足',refs=[(BASE/'new/N05-五丈原-灯前未竟-v1.png','只取右侧同一灯器、桌边、地图材质和帐帘来风方向；允许另构灯的近景，不改变道具')],camera='50mm灯与地图边缘近景，固定桌面高度；焦点留在灯芯，后方帐帘仅模糊可辨。',start='同一盏小油灯在右前方燃烧，地图仍在左侧桌面；不拍环状灯阵。',beats=[('0—2秒','灯焰稳定，背景帐布先向内动一下，说明风从帐门进入。'),('2—3秒','灯焰沿同一来风方向偏斜、变细，随后熄灭；灯芯保持原位。'),('3—5秒','留下很细一缕烟，环境亮度自然下降，地图纹理仍有微弱可读层次。')],end='灯芯暗下，细烟缓慢散开；末端可由后期短淡黑，不自动生成文字。',sound='帐帘轻扑先于灭灯，随后只留帐外风和一点呼吸尾音；禁用爆破、心跳配乐或轰鸣。',seam='灯焰偏斜和帐布动作必须因果一致。独立成章可在余烟后淡黑；不自动接夷陵救援或旧片名。',prompt='5秒单盏油灯的真人电影近景，16:9。参考图只约束右侧同一旧金属油灯、灯芯、木案、地图纸质和夜帐环境。固定50mm桌面高度近景，灯在右前方，地图边缘留在左下；后方帐帘轻微失焦。开头灯正常燃烧。背景帐布先受到从帐门进入的一阵轻风而动，随后灯焰沿同一方向倾斜、缩小并熄灭。灭灯后只留灯芯上一缕细烟，桌面受灯光照亮的部分自然变暗，仍保留微弱帐外冷光。灯器和灯芯不移动、不变形；火焰不爆炸、不变大、不复燃，不出现一整圈灯同时熄灭，不显示文字或人影冲入。声音只有帐布轻扑、帐外风和极轻的呼吸尾音；没有对白、旁白、音乐、心跳节奏或低音铺底。',checks=['先帘动再灯偏，不要无原因切成黑图或用剪辑冒充灭灯。','烟必须很细；桌灯火光消失后曝光改变自然，不是全画面同时归零。'])
]

common='MiniMax-H3；768P；16:9；真人实拍质感。以演员、布景和有因果的微动作形成电影感，不用CG火海、无人机绕圈或静态图推拉。自然皮肤与旧材质，中性环境色，局部火光/夕照保留真实暖色。请求参数不是原生输出规格承诺，下载后另核像素和帧率。'
manifest=[]
for s in shots:
 refs='\n'.join(f'{i}. [{p.name}]({p.as_posix()})\n   用途：{use}' for i,(p,use) in enumerate(s['refs'],1))
 for p,use in s['refs']:assert p.exists(),p
 beats='\n'.join(f'| {t} | {action} |' for t,action in s['beats'])
 checks='\n'.join('- '+x for x in s['checks'])
 body=f'''# {s['id']}｜{s['name']}

版本：v1 · 2026-11-16 · Prompt状态：待review · 视频状态：未生成。此文档是一条独立H3请求；本轮未提交API。

## 请求规格

- 总时长：**{s['duration']}秒**，整数请求时长；{s['edit']}，最终以实际输出动作裁切。
- {common}
- 唯一允许发声的原句：**无**。无人对白、旁白、念白或歌词；允许真实呼吸与动作声。
- 无BGM，包括原生混入的音乐、旋律、节拍和氛围低音。画面不生成字幕、片名或制作文字。

## 实际参考图与顺序

{refs}

当前接口统一发送reference_image，顺序与用途不能当作严格首尾帧锁定。只上传本条列出的图片，不把导演总案或其他人物图片一起塞入请求。

## 导演分镜

起始状态：{s['start']}

机位与景别：{s['camera']}

| 本镜时间 | 可拍动作 |
|---|---|
{beats}

结束状态：{s['end']}

声音：{s['sound']}

前后衔接：{s['seam']}

## API Prompt正文

仅使用下列正文作为视频提示词。文件标题、人物分析、时间表、检查项不能作为TTS文本；本镜不调用TTS。

```text
{s['prompt']}
```

## 动作与连续性验收

{checks}
- 查看实际视频与原声，核对口型、手/道具接触、动作起止和接点；ASR及抽帧只是辅助。
- 禁止用定格、重复素材、遮罩模糊或倒放掩盖失败。失败素材另存并写原因；本稿不能继承旧视频的任何审核结论。
- 提交按用户指定H3 SOP：预览、校验参考图、提交一次、保存任务ID；有ID只恢复同一任务。无ID未知错误不得自动重投。
'''
 name=f"{s['id']}-{s['name']}-H3-v1.md";(R/'prompts'/name).write_text(body,'utf-8')
 manifest.append(dict(id=s['id'],theme=s['theme'],name=s['name'],duration=s['duration'],document=str(R/'prompts'/name),reference_paths=[str(p) for p,use in s['refs']],reference_sha256=[hashlib.sha256(p.read_bytes()).hexdigest() for p,use in s['refs']],prompt=s['prompt'],prompt_status='待review',video_status='未生成',api_submitted=False))
(R/'prompt-manifest.json').write_text(json.dumps(dict(version='v1',date='2026-11-16',units=manifest),ensure_ascii=False,indent=2),'utf-8')
index='\n'.join(f"| {s['id']} | {s['theme']} | [{s['name']}]({(R/'prompts'/(s['id']+'-'+s['name']+'-H3-v1.md')).as_posix()}) | {s['duration']}秒 | {s['edit']} |" for s in shots)
(R/'Prompt索引.md').write_text('# 三国遗憾｜独立H3请求索引\n\n2026-11-16，v1。四组、九条独立请求，总申请时长48秒；建议工作剪辑约22—31秒，不含章间停顿。当前只整理Prompt，未生成视频，全部待review。\n\n| 编号 | 主题 | 独立生成文档 | 请求时长 | 剪辑建议 |\n|---|---|---|---|---|\n'+index+'\n\n按A→B→C→D排列仅为剪辑提议；每组也可独立制作。导演总案、来源与交接分别保存在本目录。\n','utf-8')
assert sum(s['duration'] for s in shots)==48
print(f'{len(shots)} standalone prompt documents written; all referenced files verified')
